insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('11eec31c-fea9-407b-a4ac-53da6c5f9011', 'c32ce466-ff6a-4ec1-ab5b-6cae308e4e34', $$inleiding: meldonium op de dopinglijst$$,
   $$biologie-vwo-2022-iii-meldonium-context1.png$$,
   $$In 2016 kwam het medicijn meldonium op de dopinglijst te staan. Een aantal sporters, onder wie tennisster Maria Sjarapova, werd betrapt op het gebruik van dit middel.$$, 'inline'),
  ('4aba9a40-4afc-45a4-9e80-31cc1e0598b7', 'c32ce466-ff6a-4ec1-ab5b-6cae308e4e34', $$carnitine-reabsorptie via OCTN2-symporter in de nierbuisjes (afbeelding 1)$$,
   $$biologie-vwo-2022-iii-meldonium-context2.png$$,
   $$Meldonium is een medicijn dat gebruikt wordt bij hartaandoeningen waarbij de doorbloeding van de hartspier aangetast is. De werking van meldonium berust op de verlaging van de hoeveelheid carnitine in het lichaam. Carnitine is een klein organisch molecuul dat een rol speelt bij het transport van vetzuren de mitochondriën in, en bij het dissimileren van vetzuren. Carnitine wordt door het lichaam aangemaakt, maar het merendeel krijgen we binnen door het eten van dierlijk voedsel. Meldonium remt zowel de synthese van carnitine als het transport van carnitine via transportenzymen.
Na het eten van dierlijk voedsel kan er al na twee uur carnitine worden teruggevonden in de urine. In afbeelding 1 is weergegeven hoe het transportenzym OCTN2 in de epitheelcellen van het nierbuisje reabsorptie van carnitine uit de voorurine bewerkstelligt. OCTN2 is een symporter: carnitine wordt alleen de cel in getransporteerd als er ook een Na⁺-ion via OCTN2 de cel in stroomt. Dit transport verloopt passief: OCTN2 verbruikt geen ATP.
afbeelding 1$$, 'inline'),
  ('2f791f9d-9119-4154-9f2a-398839196abb', 'c32ce466-ff6a-4ec1-ab5b-6cae308e4e34', $$tabel 1: hoeveelheden en carnitinewaarden in bloedplasma, urine en skeletspierweefsel$$,
   $$biologie-vwo-2022-iii-meldonium-context3.png$$,
   $$Tabel 1 toont de hoeveelheden bloedplasma en urine en de waarden van carnitine in bloedplasma, urine en skeletspierweefsel.
tabel 1
hoeveelheid carnitinewaarden bloedplasma mannen 3,4 L 50,6 μmol/L vrouwen 2,7 L 44,7 μmol/L urine mannen 1,7 L/dag 420 μmol/dag vrouwen 1,7 L/dag 266 μmol/dag skeletspierweefsel volwassenen 4,0 μmol/g
Naar aanleiding van afbeelding 1 en tabel 1 worden de volgende beweringen gedaan:
1 Door het transport door de epitheelcellen van de nierbuisjes wordt carnitine uitgescheiden.
2 Per dag wordt er meer carnitine uitgescheiden dan de hoeveelheid die gemiddeld in het bloedplasma aanwezig is.
3 Een vrouw van 65 kilogram met een skeletspierpercentage van 35% heeft in haar skeletspierweefsel een carnitinevoorraad van 91 μmol.$$, 'inline'),
  ('40cfe1c8-289b-444b-abb0-766999829988', 'c32ce466-ff6a-4ec1-ab5b-6cae308e4e34', $$dissimilatie en transport van palmitinezuur via carnitine (afbeelding 2)$$,
   $$biologie-vwo-2022-iii-meldonium-context4.png$$,
   $$Afbeelding 2 toont de dissimilatie en het transport van het vetzuur palmitinezuur en de rol van carnitine daarbij.
afbeelding 2
Ga ervan uit dat de oxidatie van NADH 3 ATP opbrengt, de oxidatie van FADH₂ 2 ATP opbrengt en dat elke GTP wordt omgezet in 1 ATP.$$, 'inline'),
  ('40917a3a-9665-4077-ade2-10ed96ff3477', 'c32ce466-ff6a-4ec1-ab5b-6cae308e4e34', $$meldonium remt carnitine-opname in spiercellen, die daardoor glucose als brandstof gebruiken$$,
   $$biologie-vwo-2022-iii-meldonium-context5.png$$,
   $$Doordat meldonium de opname van carnitine in skeletspiercellen en hartspiercellen remt, wordt de concentratie carnitine in deze spiercellen lager. Hierdoor gaan de spiercellen voornamelijk glucose gebruiken als brandstof. Dit is een deel van de verklaring voor het positieve effect van het medicijn bij vaatvernauwingen in de hartspier. Dissimilatie van glucose levert per zuurstofmolecuul namelijk meer ATP op dan dissimilatie van vetzuren.$$, 'inline'),
  ('8100359a-b90d-4ed7-8331-4a6f6a216798', 'c32ce466-ff6a-4ec1-ab5b-6cae308e4e34', $$verhoogde PPARα-productie door meldonium; PPARα stimuleert genexpressie$$,
   $$biologie-vwo-2022-iii-meldonium-context6.png$$,
   $$Bij gebruik van meldonium wordt ook een verhoogde productie van de stof PPARα waargenomen in onder andere hartspiercellen.
PPARα stimuleert de expressie van verschillende genen.$$, 'inline'),
  ('72a50bf8-561a-4d7e-9645-be0ab35576e9', 'c32ce466-ff6a-4ec1-ab5b-6cae308e4e34', $$PPARα vergroot oxidatieve capaciteit van mitochondriën; duursport versus krachtsport bij tennis$$,
   $$biologie-vwo-2022-iii-meldonium-context7.png$$,
   $$PPARα stimuleert onder andere de expressie van genen die de oxidatieve capaciteit vergroten: de mitochondriën kunnen ‘harder werken’. Tennis is een combinatie van duursport en krachtsport. Bij wedstrijden die wel vier uur kunnen duren speelt uithoudingsvermogen een grote rol. Bij de service en korte sprintjes speelt explosieve spierkracht een grote rol.$$, 'inline'),
  ('973f75fd-f1ef-489d-8e62-7e63d0142246', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$inleiding: kleurverandering berkenspanner veroorzaakt door een transposon$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context1.png$$,
   $$Het schoolvoorbeeld van natuurlijke selectie is de kleurverandering van de berkenspanner. Britse biologen hebben aangetoond dat de donkere kleur wordt veroorzaakt door een springend stukje DNA: een transposon.$$, 'inline'),
  ('6d75175d-cd68-4c60-8bdc-46fbb926c015', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$typica en carbonaria-vorm van de berkenspanner; mutatie in het cortex-gen (afbeelding 1)$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context2.png$$,
   $$De berkenspanner (Biston betularia) is een nachtvlinder die overdag rust op de zwart-witte stammen van berkenbomen. Door een mutatie ontstond in de negentiende eeuw in Engeland een zwarte variant van deze nachtvlinder. Toen tijdens de industriële revolutie de berkenstammen in industriegebieden volledig donker kleurden door roetaanslag, nam de frequentie van de zwarte vorm in deze gebieden sterk toe. De oorspronkelijke vorm wordt typica genoemd, de zwarte vorm carbonaria (afbeelding 1). De kleurverandering blijkt veroorzaakt te zijn door een specifieke mutatie in het cortex-gen, dat een rol speelt in de vleugelaanleg van de berkenspanner.
afbeelding 1$$, 'inline'),
  ('c224e7fd-3a1e-40b7-bc70-4d6cbe65e72e', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$frequentie van carbonaria-fenotype en -allel in de tijd (afbeelding 2)$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context3.png$$,
   $$De veranderingen in de frequentie van het carbonaria-fenotype en het carbonaria-allel zijn weergegeven in afbeelding 2. De grafieken zijn het resultaat van simulaties op basis van enkele tellingen.
afbeelding 2$$, 'inline'),
  ('02e10c83-6511-4814-99f7-2c9f1b43e286', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$discussie over hardy-weinberg-evenwicht in de populatie in 1900$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context4.png$$,
   $$Uit de informatie is af te leiden dat het discutabel is dat er in 1900 sprake was van een hardy-weinberg-evenwicht in de populatie in de industriegebieden. Daarom zou de regel van Hardy-Weinberg eigenlijk niet toegepast mogen worden.$$, 'inline'),
  ('a223722c-b43a-41f0-8c07-ed1dfc3b8131', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$werking en verplaatsingsstappen van een transposon (afbeelding 3)$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context5.png$$,
   $$Een transposon of springend gen is een mobiel stukje dubbelstrengs DNA dat binnen het hele genoom van plaats kan veranderen. Dat gebeurt met behulp van het enzym transposase, dat de nucleotidesequentie uit de DNA-streng knipt en op een nieuwe plaats er weer in plakt. Een transposon bevat minimaal een stuk DNA waarin het transposase-gen aanwezig is. Aan elk uiteinde van het transposon bevindt zich een nucleotidesequentie met een aantal herhalingen (terminal repeats). Het verplaatsen van een transposon verloopt in een aantal stappen (afbeelding 3).
afbeelding 3$$, 'inline'),
  ('b619fe44-a4a8-4285-957b-9dd26b2a31fe', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$het cortex-gen is veranderd door een transposon$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context6.png$$,
   $$Het cortex-gen blijkt door een transposon veranderd te zijn.$$, 'inline'),
  ('6f11371a-5198-4813-8388-c340e53e9db2', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$transposons en crossing-over als bronnen van genetische variatie; drie beweringen$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context7.png$$,
   $$Door het vermogen om gedeeltes van het DNA over chromosomen te verplaatsen, zijn de transposons een belangrijke bron van genetische variatie. Ook crossing-over veroorzaakt genetische variatie. Over beide bronnen van genetische variatie worden de volgende beweringen gedaan:
1 Beide vinden vooral plaats tijdens mitose.
2 Bij beide verandert een deel van een nucleotideketen van plaats.
3 Bij beide vindt uitwisseling van informatie alleen plaats tussen twee homologe chromosomen.$$, 'inline'),
  ('cf361990-da5f-4aab-bfe1-d6440dcd4f9a', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$PCR met primers X, Y en Z op het carb- en typ-allel (afbeelding 4)$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context8.png$$,
   $$Met behulp van PCR en gel-elektroforese hebben de onderzoekers de aanwezigheid of afwezigheid van het transposon dat verantwoordelijk is voor het carbonaria-fenotype vastgesteld bij een familie berkenspanners. Bij de PCR is gebruikgemaakt van de drie primers X, Y en Z. In afbeelding 4 is schematisch weergegeven hoe het allel waarin het transposon is ingevoegd (carb) en het oorspronkelijke allel zonder dit transposon (typ), zijn opgebouwd. Met pijlen is de richting van de replicatie aan de primers weergegeven.
afbeelding 4$$, 'inline'),
  ('66593167-bb0c-46f0-acb5-2cb910bc8351', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$gel-elektroforese van de PCR-fragmenten (afbeelding 5)$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context9.png$$,
   $$Bij gel-elektroforese worden de DNA-fragmenten gescheiden die met behulp van PCR zijn gevormd. Het resultaat is weergegeven in afbeelding 5. De eenheid kb (kilobase) is een maat voor de lengte van een DNA-fragment.
afbeelding 5
De onderzoekers geven aan dat de primers X en Z bij het carb-allel te ver van elkaar verwijderd zijn om een DNA-fragment op te leveren. De DNA- fragmenten die wel worden gevormd, zijn zichtbaar als oplichtende bandjes na gel-elektroforese.$$, 'inline'),
  ('f5e64af2-6230-46c3-b276-0fe440099f45', 'eec2fd6f-901f-4012-8119-0b5f77edd1c6', $$sterke afname carbonaria-fenotype tussen 1980-1990 bij gelijkblijvende populatie; drie gegevens$$,
   $$biologie-vwo-2022-iii-zwart-door-springend-gen-context10.png$$,
   $$In afbeelding 2 is te zien dat de frequentie van het carbonaria-fenotype in de populatie sterk is afgenomen tussen 1980 en 1990. De totale populatie berkenspanners is ongeveer gelijk gebleven. Drie gegevens zijn:
1 De luchtverontreiniging is tussen 1980 en 1990 verminderd.
2 Het transposon kan uit het cortex-gen ‘springen’.
3 Tussen 1980 en 1990 is het aantal berkenbomen afgenomen.$$, 'inline'),
  ('f30f2815-b521-48c4-a8b9-a08650f76852', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$inleiding: onkruidbestrijding door uithongeren met fosfiet$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context1.png$$,
   $$Sinds het ontstaan van de landbouw strijden boeren tegen onkruid: planten die zonlicht, voedingsstoffen en water ‘wegkapen’ van de geteelde gewassen. Naast de bekende methoden van onkruidbestrijding is er nu een nieuwe methode ontwikkeld: uithongeren.$$, 'inline'),
  ('0b7ed8d4-16c6-42cc-b9d6-019d88dfd0d6', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$onkruidsoorten zijn vooral pioniersoorten$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context2.png$$,
   $$De soorten die door landbouwers als onkruid worden gezien zijn voornamelijk pioniersoorten. Door bepaalde eigenschappen van pioniersoorten komen deze soorten veel voor op akkers.$$, 'inline'),
  ('bc316b7c-5cb4-4c60-af7f-3245bedf4e9d', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$herbiciden ingedeeld naar werking, waaronder PSII-remmers$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context3.png$$,
   $$In de reguliere landbouw is het toedienen van herbiciden (onkruidbestrijdingsmiddelen) de meest gebruikte methode om groei van onkruid tegen te gaan. Herbiciden worden ingedeeld op hun werking. Zo zijn er bijvoorbeeld fotosysteem-II-remmers (PSII-remmers).$$, 'inline'),
  ('b920a35a-834d-49fb-ab05-33d0d1765c28', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$PSII-remmers blokkeren elektronentransport in fotosysteem II; drie beweringen$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context4.png$$,
   $$PSII-remmers verstoren de lichtreactie doordat het elektronentransport in fotosysteem II wordt geblokkeerd. Drie beweringen over fotosysteem II zijn:
1 Fotosysteem II bevindt zich op het buitenmembraan van chloroplasten.
2 Een blokkade van het elektronentransport in fotosysteem II leidt tot een verminderde splitsing van water.
3 Een remming van fotosysteem II zal leiden tot een remming van de donkerreactie.$$, 'inline'),
  ('2a3ba9dc-9833-40ae-970d-de4b28483dc2', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$EPSPS-remmer glyfosaat (Roundup) en glyfosaatresistente gewassen$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context5.png$$,
   $$Er zijn ook herbiciden die het enzym EPSPS remmen. Een plant heeft dit enzym nodig om aromatische aminozuren te synthetiseren. Het biotechnologisch bedrijf Monsanto introduceerde de EPSPS-remmer glyfosaat onder de naam Roundup. Gebruik van dit middel is toegenomen nadat Monsanto genetisch gemodificeerde landbouwgewassen op de markt bracht waarin resistentie tegen glyfosaat was ingebouwd.$$, 'inline'),
  ('395a8cb9-a135-4625-b1d9-b7799d7b7d80', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$glyfosaat remt bijna alle stofwisselingsprocessen in niet-resistente planten$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context6.png$$,
   $$In planten zonder glyfosaat-resistentie zorgt glyfosaat voor een remming van bijna alle stofwisselingsprocessen.$$, 'inline'),
  ('6ac891ff-7581-43bb-96ae-cfd42cf24823', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$lage glyfosaatconcentratie in oppervlaktewater; halveringstijd 7-14 dagen$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context7.png$$,
   $$Glyfosaat is schadelijk voor organismen die in water leven. De concentratie glyfosaat die aanwezig is in het oppervlaktewater, is echter laag. Uit een onderzoek blijkt dat de halveringstijd van glyfosaat in het aquatisch milieu 7 tot 14 dagen is.$$, 'inline'),
  ('922df02c-cd16-4d37-9dab-2a8ec9dd3f2c', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$toenemende herbicideresistentie bij onkruidsoorten in de VS (afbeelding 1)$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context8.png$$,
   $$Gebruik van pesticiden leidt – als gevolg van evolutie – tot ontwikkeling van resistentie bij onkruidsoorten. In het diagram in afbeelding 1 is de ontwikkeling van resistentie tegen de beschreven herbiciden bij onkruidsoorten in de VS weergegeven.
afbeelding 1$$, 'inline'),
  ('98f47757-6ae2-4ab5-98ef-ee60b272c64b', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$resistentie binnen een groep onkruidsoorten als voorbeeld van analogie$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context9.png$$,
   $$In afbeelding 1 is te zien dat steeds meer onkruidsoorten resistentie hebben ontwikkeld tegen een van beide typen herbiciden. De resistenties bij verschillende soorten binnen één groep zijn een voorbeeld van analogie.$$, 'inline'),
  ('5a15919b-da9d-45a5-a072-9df5c2544ec0', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$fosfaat versus fosfiet: opname via fosfaattransportenzymen, niet bruikbaar voor assimilatie$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context10.png$$,
   $$Om het resistentieprobleem te omzeilen hebben wetenschappers gezocht naar een andere aanpak om onkruid te bestrijden. Voor de assimilatie van fosforhoudende organische stoffen kunnen planten alleen fosfaat (PO₄³⁻) gebruiken. Deze stof is een van de hoofdbestanddelen van kunstmest. Fosfor in de vorm van fosfiet (PO₃³⁻) kan door plantencellen wel worden opgenomen via de fosfaat- transportenzymen, maar kan niet worden gebruikt voor assimilatieprocessen. Als een landbouwgewas zo kan worden aangepast dat het gewas fosfiet wel kan benutten, zou het een groot voordeel hebben ten opzichte van onkruid.$$, 'inline'),
  ('0f3061fd-64d4-48d9-8912-11e6d6c2d338', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$drie organische stoffen: chlorofyl, NADH, RNA$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context11.png$$,
   $$Enkele organische stoffen zijn:
1 chlorofyl
2 NADH
3 RNA$$, 'inline'),
  ('3512e343-21b4-47d6-88a2-db3dcfbb09e1', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$ptxD-gen in katoenplanten maakt fosfiet bruikbaar als fosforbron (afbeelding 2)$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context12.png$$,
   $$Amerikaanse onderzoekers zijn erin geslaagd het bacteriële ptxD-gen in te bouwen in een chromosoom van katoenplanten (Gossypium sp.). Dit gen codeert voor een enzym dat de oxidatie van fosfiet tot fosfaat katalyseert. Transgene planten, waarin de expressie van het ptxD-gen was vastgesteld, werden onderling gekruist. De zaden uit deze kruisingen werden na kieming opgekweekt. Een gedeelte kreeg hierbij fosfaat als fosforbron, een ander gedeelte kreeg fosfiet. Als controle werden wildtype katoenplanten op dezelfde manier gekweekt. Uit de resultaten (afbeelding 2) werd duidelijk dat door het inbrengen van het ptxD-gen de planten fosfiet als fosforbron konden gebruiken.
afbeelding 2$$, 'inline'),
  ('121625fa-93f9-4a74-ada4-f8061fad9c90', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$groep slechte groeiers in de F1 van transgene planten met fosfiet als fosforbron$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context13.png$$,
   $$In de F1 van de transgene planten met fosfiet als fosforbron, komt een groep slechte groeiers voor.$$, 'inline'),
  ('880b59d4-b45a-41d9-a8c1-dad23780a065', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$proefopstellingen met Brachypodium distachyon en transgene katoenplanten bij fosfaat/fosfiet (afbeelding 3, afbeelding 4)$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context14.png$$,
   $$In een vervolgexperiment werden zaden van transgene katoenplanten ingezaaid, samen met zaden van het grasachtige onkruid Brachypodium distachyon. De planten werden opgekweekt in een proefopstelling met een bodem zonder fosforbron, in een proefopstelling met een bodem met fosfaat, en in twee proefopstellingen met bodems met verschillende hoeveelheden fosfiet. In afbeelding 3 zijn de planten te zien na zes weken (gezien vanaf schuin-boven en vanaf de zijkant). In afbeelding 4 is het totale drooggewicht na zes weken van de bovengrondse delen van drie representatieve planten uit elke proefopstelling weergegeven.
afbeelding 3
afbeelding 4$$, 'inline'),
  ('8afb481b-6da7-4e81-949c-cb2a8fdde197', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$fosforgehalte van fosfiet versus fosfaat verklaart het groeiverschil niet volledig$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context15.png$$,
   $$Een milligram fosfiet bevat meer fosfor dan een milligram fosfaat, maar dit is niet voldoende om het verschil in groei van de transgene katoenplanten op de proefopstellingen met fosfaat (80 mg/kg) en fosfiet (80 mg/kg) te verklaren.$$, 'inline'),
  ('ee5e3855-f037-41d1-bdae-e393a56dfdc2', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$fosfietbemesting vereist aanvulling van de stikstofvoorraad; drijfmest of groenbemesting$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context16.png$$,
   $$Om fosfiet in de akkerbouw toe te passen als effectieve onkruidbestrijdingsmethode zal de bemesting moeten worden aangepast. Na de oogst moet met fosfiet bemest worden en moet de stikstofvoorraad worden aangevuld. Twee manieren om de stikstofvoorraad aan te vullen zijn:
− drijfmest (urine en uitwerpselen van vee) uitrijden
− groenbemesting toepassen door er vlinderbloemigen te laten groeien die in symbiose leven met knolletjesbacteriën, en die vervolgens onder te ploegen$$, 'inline'),
  ('d0711d20-55d1-4f02-abd9-521a758b670d', 'f56cad0f-eabd-42a8-9606-1994aec0e1ed', $$fosfaat uit kunstmest in oppervlaktewater veroorzaakt algenbloei$$,
   $$biologie-vwo-2022-iii-fosfietbemesting-in-strijd-tegen-onkruid-context17.png$$,
   $$Als gevolg van kunstmestgebruik in de landbouw komt veel fosfaat in het oppervlaktewater, wat leidt tot algenbloei.$$, 'inline'),
  ('be23ea09-d522-4c91-8024-0d7943ec773c', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$inleiding: het domesticatiesyndroom bij huisdieren, nog onverklaard$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context1.png$$,
   $$Het was Charles Darwin al opgevallen dat onze huisdieren een verzameling eigenschappen vertonen die je niet ziet bij hun wilde verwanten. Dit wordt het domesticatiesyndroom genoemd. Een internationale groep evolutiebiologen denkt hiervoor de verklaring te hebben gevonden.$$, 'inline'),
  ('9884becf-0176-41b8-a75a-4ab4957b36c9', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$domesticatie en gedeelde uiterlijke kenmerken van huisdieren, o.a. witte vlekken (afbeelding 1)$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context2.png$$,
   $$Domesticatie is het proces waarmee de mens door selecteren en kruisen de eigenschappen van dieren heeft veranderd, zodat deze dieren steeds geschikter zijn voor het leven dicht bij en in dienst van de mens. Gedomesticeerde dieren (huisdieren) zijn tam: zij hebben geen angstige of agressieve reacties op hun menselijke verzorgers. Gedomesticeerde dieren delen echter ook eigenschappen waar in eerste instantie niet op geselecteerd was. Ze hebben vaak witte vlekken in de vacht (afbeelding 1), kleine tanden, een korte snuit, hangoren en/of een krulstaart; eigenschappen die hun wilde soortgenoten niet hebben.
afbeelding 1$$, 'inline'),
  ('c3169343-1f25-4d56-9593-ca31bec65e34', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$Darwins hypothese over milieu-oorzaak; verwachting bij ontsnapte huisdieren en methodologische problemen 1-3$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context3.png$$,
   $$Darwin veronderstelde dat het domesticatiesyndroom verband houdt met de milde abiotische omstandigheden en de ruime voedselvoorziening van huisdieren.
Uit Darwins veronderstelling volgt de verwachting dat nakomelingen van ontsnapte huisdieren hun typische witte vlekken binnen enkele generaties in het wild weer zullen verliezen. Om te weten te komen of dit echt zo is, zouden de eigenschappen van nakomelingen van ontsnapte huisdieren onderzocht moeten worden. Dit is lastig, want huisdieren die ontsnappen en verder leven in het wild komen maar weinig voor. Andere problemen van zo’n onderzoek zouden zijn:
1 Ontsnapte huisdieren kunnen ook paren en nakomelingen krijgen met wilde soortgenoten.
2 Er zullen maar weinig nakomelingen van ontsnapte huisdieren teruggevonden worden.
3 Dieren met witte vlekken vallen eerder ten prooi aan predatoren. Goed onderzoek is betrouwbaar en valide.$$, 'inline'),
  ('f57b8c5e-7e03-491f-8539-42a0893989f9', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$domesticatiesyndroom eenvoudig te creëren bij vossen (15 generaties); drie mogelijke genetische verklaringen$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context4.png$$,
   $$Het domesticatiesyndroom creëren is relatief eenvoudig. Dit is aangetoond bij vossen. Uit de wilde populatie kunnen binnen vijftien generaties tamme vossen met witte vlekken in de vacht gefokt worden door steeds de tamste dieren te selecteren om te kruisen. Het domesticatiesyndroom verklaren is echter niet eenvoudig. Voor de genetische oorsprong van het domesticatiesyndroom zijn er drie mogelijke verklaringen:
1 Het domesticatiesyndroom komt tot uiting als er een combinatie van recessieve allelen van een aantal verschillende genen aanwezig is.
2 Het domesticatiesyndroom komt tot uiting als er een combinatie van (onvolledig) dominante allelen van een aantal verschillende genen aanwezig is.
3 Het domesticatiesyndroom wordt bepaald door een mutatie van een enkel gen.$$, 'inline'),
  ('3ecfc966-23fc-4433-98c8-fcfff4459cec', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$lage mutatiesnelheid van eukaryote genomen maakt verklaring 3 onaannemelijk$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context5.png$$,
   $$Eukaryote genomen muteren naar schatting met een snelheid van ongeveer 1 x 10⁻⁶ mutaties per gen per generatie. Deze mutatiesnelheid in combinatie met de bevinding bij vossen, maakt verklaring 3 niet aannemelijk.$$, 'inline'),
  ('810bd082-af1e-4f57-b785-6ebc37661de6', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$kruising van tamme met wilde vossen: alle nakomelingen hebben het domesticatiesyndroom$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context6.png$$,
   $$Stel dat je tamme vossen met het domesticatiesyndroom kruist met niet- tamme vossen uit een wilde populatie en dat de eerste generatie nakomelingen alle het domesticatiesyndroom hebben.$$, 'inline'),
  ('fb326757-6616-45a4-b4fa-0619345674da', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$ontwikkeling van de neurale-lijstcellen als gezamenlijke oorzaak (afbeelding 2)$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context7.png$$,
   $$De evolutiebiologen veronderstellen dat het domesticatiesyndroom bij verschillende zoogdiersoorten dezelfde oorzaak heeft, namelijk de manier waarop de neurale-lijstcellen zich ontwikkelen. Vroeg in de embryonale ontwikkeling van zoogdieren ontstaat de neurale buis. Deze buis bevindt zich aan de rugzijde en zal later in de ontwikkeling uitgroeien tot het centraal zenuwstelsel. Aan weerszijden van deze buis ontstaat een groep neurale-lijstcellen (afbeelding 2). Deze cellen migreren naar andere plaatsen in het embryo. Daar groeien ze uit tot verschillende weefsels en beïnvloeden ze de ontwikkeling van naburige weefsels.
afbeelding 2$$, 'inline'),
  ('df82c813-61d3-4410-bbb7-4b433e2f0550', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$verondersteld verschil in aantal en migratie van neurale-lijstcellen bij gedomesticeerde dieren$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context8.png$$,
   $$Er wordt verondersteld dat bij gedomesticeerde dieren het aantal neurale- lijstcellen en de migratie ervan anders zijn dan bij wilde soortgenoten.$$, 'inline'),
  ('0db118fe-7b15-44f9-a120-9e71e57c4bef', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$neurale-lijstcellen als multipotente stamcellen; drie beweringen$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context9.png$$,
   $$Neurale-lijstcellen behoren tot de multipotente stamcellen. Multipotente stamcellen zijn verder gedifferentieerd dan pluripotente stamcellen. Drie beweringen over multipotente stamcellen in het algemeen zijn:
1 Multipotente stamcellen ontstaan bij de klievingsdelingen.
2 Multipotente stamcellen kunnen differentiëren tot omnipotente (totipotente) stamcellen.
3 Multipotente stamcellen kunnen nieuwe multipotente stamcellen vormen.$$, 'inline'),
  ('13c6e982-4e67-4c18-84ce-bc7af5c038f7', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$migratieroutes van neurale-lijstcellen en celtypen die eruit ontstaan (afbeelding 3)$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context10.png$$,
   $$De evolutiebiologen veronderstellen dat we, door te selecteren op tam gedrag bij het fokken van onze huisdieren, onbewust hebben geselecteerd op dieren met minder neurale-lijstcellen op de plaats van bestemming. In afbeelding 3 is met pijlen afbeelding 3 weergegeven wat de routes zijn van de migrerende neurale- lijstcellen in een embryo. Enkele celtypen die uit neurale-lijstcellen ontstaan, zijn:
− beencellen
− kraakbeencellen
− tandbeenvormende cellen
− cellen van de bijnier
− bepaalde neuronen
− pigmentcellen$$, 'inline'),
  ('e89abb1a-0924-4b38-944d-853ee3ec3508', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$neurale-lijstceltheorie verbindt afwijkende fysiologie met afwijkende uiterlijke kenmerken$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context11.png$$,
   $$De neurale-lijstceltheorie van de evolutiebiologen biedt een verklaring voor het verband tussen de afwijkende fysiologie (via zenuwstelsel en bijnierhormonen) en de afwijkende uiterlijke kenmerken van onze huisdieren (pigmentatie en vorm van oren, staart, schedel en tanden).$$, 'inline'),
  ('04bb3688-367f-4e12-9253-5d532a05e610', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$stressrespons ontbreekt bij gedomesticeerde dieren; snelle en langzamere respons$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context12.png$$,
   $$Bij veel gedomesticeerde dieren ontbreekt de ‘stressrespons’ (de fysiologische reactie op een stressprikkel) bij contact met mensen vrijwel geheel. De stressrespons bestaat uit een snelle respons en een langzamere respons.$$, 'inline'),
  ('ad4829ac-4e22-4e96-af8c-20d96e39806e', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$snelle respons: hormoonafgifte onder invloed van het autonome zenuwstelsel$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context13.png$$,
   $$De snelle respons leidt tot de afgifte van een hormoon onder invloed van het autonome zenuwstelsel.$$, 'inline'),
  ('2a241bf1-b3f7-4a41-a5fd-90f72cbe3e81', '9dad9153-1db2-48dc-86fd-730e6d12372a', $$langzamere respons: cortisolafgifte via hypothalamus en hypofyse$$,
   $$biologie-vwo-2022-iii-domesticatiesyndroom-context14.png$$,
   $$De langzamere respons leidt tot de afgifte van het hormoon cortisol. De afgifte hiervan gebeurt onder invloed van de hypothalamus en de hypofyse.$$, 'inline'),
  ('09a421ba-e1dc-45b9-93b7-d1b5dcf35a50', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$inleiding: poliovaccin met behulp van planten produceren$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context1.png$$,
   $$Polio of kinderverlamming is een infectieziekte die wordt veroorzaakt door het poliovirus. Al in 1988 is de WHO (World Health Organization) een campagne gestart om het poliovirus wereldwijd uit te roeien, maar nog steeds is dit doel niet gehaald. Productie van een goedkoop poliovaccin met behulp van planten kan mogelijk het laatste zetje geven.$$, 'inline'),
  ('7b5ed1ef-d9b5-40f8-8ff0-ae41a529bf2c', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$besmetting, vermenigvuldiging en aantasting van het zenuwstelsel door het poliovirus (afbeelding 1)$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context2.png$$,
   $$Besmetting met het poliovirus vindt vooral plaats via water of voedsel dat met ontlasting besmet is. Hierna vermenigvuldigt het virus zich in de cellen van de darmwand, waarna het wekenlang in de ontlasting aangetroffen kan worden. Meestal treedt een lokale immuunrespons op zodat geen of slechts griepachtige verschijnselen optreden. In één tot twee procent van de gevallen gebeurt dit niet en bereikt het virus via het lymfestelsel het centraal zenuwstelsel waar het vervolgens het ruggenmerg en/of de hersenstam aantast. In afbeelding 1a zijn gezond ruggenmerg, neuronen en een spier te zien; in 1b en 1c de gevolgen na aantasting van het ruggenmerg door een polio-infectie.
afbeelding 1
a b c$$, 'inline'),
  ('9492fd96-24a0-4530-8718-494f10d3d433', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$de weergegeven neuronen in afbeelding 1 zijn motorische neuronen$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context3.png$$,
   $$De weergegeven neuronen in afbeelding 1 zijn motorische neuronen.$$, 'inline'),
  ('4d619a0e-e5c8-4d0d-8efc-623dab5c45f8', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$spierfunctie acht jaar na de infectie gedeeltelijk hersteld$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context4.png$$,
   $$Acht jaar na de polio-infectie is de spierfunctie weer gedeeltelijk hersteld.$$, 'inline'),
  ('78b9838f-0773-433d-b18b-e2f0bc4c469d', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$effecten van polio op het autonome en animale zenuwstelsel$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context5b.png$$,
   $$Een polio-infectie kan effect hebben op het autonome zenuwstelsel en op het animale zenuwstelsel. Enkele effecten van polio zijn:
1 lage bloeddruk
2 versnelde darmperistaltiek
3 aantasting van de kniepeesreflex
4 moeite met hoesten$$, 'inline'),
  ('4a1c7a50-5fed-4733-ae71-a78602810477', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$het poliovirus infecteert slechts een bepaald type neuronen$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context6.png$$,
   $$Het poliovirus infecteert alleen een bepaald type neuronen.$$, 'inline'),
  ('3e92a752-7a48-4802-9bb4-8406d4c144a1', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$beademing met de ijzeren long bij verlamde ademhalingsspieren (afbeelding 2)$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context7.png$$,
   $$Polio kan leiden tot verlamming van de ademhalingsspieren. In de vorige eeuw werden poliopatiënten die niet meer zelfstandig konden ademen in een ‘ijzeren long’ geplaatst. Dit is een luchtdichte stalen buis met een isolatie-ring rond de nek van de patiënt (afbeelding 2). Door de luchtdruk in de buis te regelen kan de werking van de ademhalingsspieren worden overgenomen.
afbeelding 2$$, 'inline'),
  ('4fc6e8cf-804d-4594-a42d-098c83faab1e', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$polio kan de middenrifspieren verlammen$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context8.png$$,
   $$Door polio kunnen de middenrifspieren verlamd raken.$$, 'inline'),
  ('b921b9ba-7fd2-4fe8-8e0c-3cbec79f5d70', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$het poliovirus als positief-sense enkelstrengs RNA-virus; vermenigvuldigingsschema (afbeelding 3)$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context9.png$$,
   $$Het poliovirus is een enkelstrengs positief-sense RNA-virus. Positief- sense (+) betekent dat de enkele streng RNA de coderende basenvolgorde bevat. Na aankomst in de darmen wordt het virus vermenigvuldigd in darmwandcellen. De vermenigvuldiging van het poliovirus is weergegeven in afbeelding 3.
afbeelding 3$$, 'inline'),
  ('d89b7ba7-94e9-44ed-91d1-031567d78a34', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$drie beweringen over de vermenigvuldiging van het poliovirus$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context10.png$$,
   $$Over de vermenigvuldiging van het poliovirus worden de volgende beweringen gedaan:
1 Het poliovirus wordt in de cel opgenomen door middel van endocytose.
2 De polymerase die ontstaat na translatie is een RNA-polymerase.
3 Als matrijs van nieuw viraal RNA wordt positief-sense RNA gebruikt.$$, 'inline'),
  ('e6b3ecf9-ba76-457d-b018-065daaacdd8f', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$uitroeiing van infectieziekten; symptoomloze verspreiding bemoeilijkt uitroeiing van polio$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context11.png$$,
   $$Tot nu toe is slechts één veroorzaker van een menselijke infectieziekte uitgeroeid, namelijk het pokkenvirus. Ook het poliovirus is mogelijk uit te roeien omdat de mens de enige gastheer is. Het uitblijven van waarneembare verschijnselen bij een polio-infectie maakt het uitroeien van polio echter moeilijker.$$, 'inline'),
  ('a9662635-eaee-4b48-a134-f5a8fa21c014', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$salkvaccin en sabinvaccin vergeleken; immunoglobulineconcentraties na vaccinatie (afbeelding 4)$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context12.png$$,
   $$Door vaccinatiecampagnes is het aantal gevallen van polio sinds 1988 met 98% afgenomen. Toch worden elk jaar nog steeds tientallen ziektegevallen waargenomen. Wereldwijd worden twee vaccins gebruikt: het salkvaccin en het sabinvaccin. Het salkvaccin wordt in een spier geïnjecteerd en bevat ‘dode’ virussen die geen cellen kunnen binnendringen, maar wel een immuunrespons kunnen oproepen. Het sabinvaccin wordt via de mond (op een suikerklontje) toegediend en bevat ‘levende’ verzwakte virussen die nog wel in geringe mate vermenigvuldigd kunnen worden, maar niet meer ziekteverwekkend zijn. In afbeelding 4 is de concentratie immunoglobulinen na vaccinatie met het salkvaccin en na vaccinatie met het sabinvaccin weergegeven. De eenheden op de y-assen zijn hetzelfde (arbitraire eenheid).
afbeelding 4$$, 'inline'),
  ('50cce75b-0e51-4186-9e33-2a2066cd3853', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$ontwikkeling van VLP''s in transgene planten als nieuw vaccin (afbeelding 5)$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context13.png$$,
   $$Doordat het sabinvaccin verzwakte ‘levende’ virussen bevat, is uitroeiing van polio met behulp van dit vaccin niet mogelijk. Er moeten daarom nieuwe vaccins worden ontwikkeld die goed, goedkoop en veilig zijn. Onderzoekers in Norwich (VK) hebben transgene planten ontwikkeld die eiwitten produceren die op poliovirusdeeltjes lijken. Dit zijn VLP’s (virus- like particles). Deze VLP’s roepen wel dezelfde immuunrespons op als het poliovirus, maar bevatten geen genetisch materiaal van dat virus. De productie van VLP’s is schematisch weergegeven in afbeelding 5.
afbeelding 5
1 inbrengen van het gen in een plasmide
2 inbrengen van de plasmide en vermenigvuldiging ervan in de bacterie Escherichia coli
3 isoleren van de plasmiden uit E. coli
4 inbrengen van de plasmiden in de bacterie Agrobacterium tumefaciens
5 besmetting van planten met gemodificeerde A. tumefaciens
6 expressie van het gen in planten
7 extractie en zuivering van de geproduceerde eiwitten$$, 'inline'),
  ('f096e601-0c4e-4b22-9b12-a8a835fe5d58', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$stap 1: het benodigde gen wordt ingebracht in een plasmide uit E. coli$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context14.png$$,
   $$In stap 1 wordt het gen dat nodig is voor de immuunrespons, ingebracht in een plasmide uit E. coli.$$, 'inline'),
  ('dc8e7788-44a9-4384-a832-e38ad50c4119', '68fd6e53-07c3-490f-a300-11d5598fb0a9', $$orale of intraveneuze toediening van VLP''s; factoren in het spijsverteringskanaal$$,
   $$biologie-vwo-2022-iii-planten-maken-nieuw-poliovaccin-context15.png$$,
   $$De vaccins met de VLP’s zouden oraal of door injectie toegediend kunnen worden. Voordeel van injectie is dat de VLP’s zeker het inwendig milieu bereiken. Wanneer de VLP’s oraal toegediend worden, bijvoorbeeld op een suikerklontje, is dat onzeker. Enkele factoren in het spijsverteringskanaal zijn:
1 lage pH
2 aanwezigheid van lipase
3 aanwezigheid van trypsine$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('57032e1f-9652-490e-8fb3-1215b493a871', 'c32ce466-ff6a-4ec1-ab5b-6cae308e4e34', 1,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
   '["actief transport", "passief transport", "symporter", "concentratiegradiënt", "Na-K-pomp"]'::jsonb,
   $$Verklaren dat passief carnitinetransport via een symporter indirect toch ATP kost, vanwege de Na⁺-K⁺-pomp die de benodigde concentratiegradiënt in stand houdt.$$,
   $$biologie-vwo-2022-iii-meldonium-vraag1.png$$, $$2p 1 Leg uit, aan de hand van afbeelding 1, dat reabsorptie van carnitine in de nieren toch ATP kost.$$, array['11eec31c-fea9-407b-a4ac-53da6c5f9011', '4aba9a40-4afc-45a4-9e80-31cc1e0598b7']::uuid[]),
